function calculateBMI(weight, height) {
    const bmi = weight / (height * height);
    if (bmi < 18.5) return { bmi, category: '偏瘦' };
    if (bmi < 24) return { bmi, category: '正常' };
    if (bmi < 28) return { bmi, category: '偏胖' };
    return { bmi, category: '肥胖' };
}

